var produtosJS = {
    init: function () {
        $('.selected2').select2();

        // Bind para o botão de exclusão
        $("#btDelete").off("click").on("click", function (e) {
            e.preventDefault();
            var produtoId = $(this).data("id");
            notify.confirmYesNo(
                "danger",
                "Confirmação de Exclusão",
                "Tem certeza que deseja excluir este produto?",
                function (confirmed) {
                    if (confirmed) {
                        gl.Post("Excluir", "ProdutosPage", { id: produtoId }, true, function (r) {
                            window.location.href = "/ProdutosPage";
                        });
                    }
                },
                null,
                "Sim, excluir",
                "Cancelar"
            );
        });

        // Bind para o botão de duplicação
        $("#btDuplicar").off("click").on("click", function (e) {
            e.preventDefault();
            var produtoId = $(this).data("id");
            notify.confirmYesNo(
                "primary",
                "Confirmação de Duplicação",
                "Tem certeza que deseja duplicar este produto?",
                function (confirmed) {
                    if (confirmed) {
                        gl.Post("Duplicar", "ProdutosPage", { id: produtoId }, true, function (r) {
                            if (r.success) {
                                notify.success("Sucesso", "Produto Duplicado.");
                                setTimeout(function() {
                                    window.location.href = "/ProdutosPage/Gerenciar/" + r.produtoId;
                                }, 1000);
                            } else {
                                notify.error("Erro", r.message);
                            }
                        });
                    }
                },
                null,
                "Sim, duplicar",
                "Cancelar"
            );
        });


        // Inicializa os handlers de taxas
        produtosJS.initTaxas();

        // Máscaras
        Basics.currencyMask(".currency");
        Basics.taxaMask(".taxamask");

        // Função para alternar campos conforme Modalidade
        function toggleModalidadeFields() {
            var modalidade = $('#modalidadeDropdown').val();
            if (modalidade === "Produtividade") {
                $('#produtividadeFields').show();
                $('#custeioFields').hide();
            } else if (modalidade === "Custeio") {
                $('#produtividadeFields').hide();
                $('#custeioFields').show();
            } else {
                $('#produtividadeFields, #custeioFields').hide();
            }
        }
        $('#modalidadeDropdown').off('change').on('change', toggleModalidadeFields);
        toggleModalidadeFields();



        // Função para exibir ou ocultar os campos adicionais para Tipo1
        function toggleTipo1Fields() {
            if ($("#chkTipo1").is(":checked")) {
                $(".tipo1Fields").show();
            } else {
                $(".tipo1Fields").hide();
            }
        }
        // Associa o evento de mudança no checkbox Tipo1
        $("#chkTipo1").off("change").on("change", toggleTipo1Fields);
        toggleTipo1Fields();




        // Função para alternar campos para Replantio
        function toggleReplantioFields() {
            var replantio = $('#replantioDropdown').val();
            if (replantio === "Cobertura de produção") {
                $(".coberturaProducaoFields").show();
                $(".coberturaAdicionalFields").hide();
            } else if (replantio === "Cobertura adicional") {
                $(".coberturaProducaoFields").hide();
                $(".coberturaAdicionalFields").show();
            } else {
                $(".coberturaProducaoFields, .coberturaAdicionalFields").hide();
            }
        }
        $('#replantioDropdown').off('change').on('change', toggleReplantioFields);
        toggleReplantioFields();




        // Toggle para Subvenções
        $('#utilizaSubvFederal').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#subvFederalContainer').show();
            } else {
                $('#subvFederalContainer').hide();
                $('#subvFederalContainer select').val("");
            }
        });
        $('#utilizaSubvEstadual').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#subvEstadualContainer').show();
                var $lst = $('#listaSubvencoesEstaduais');
                if ($lst.length && $lst.children().length === 0)
                    $lst.html('<p class="text-muted small mb-0">' + ($lst.data('empty-msg') || 'Nenhuma subvenção adicionada. Use o seletor acima para adicionar.') + '</p>');
            } else {
                $('#subvEstadualContainer').hide();
                var $multi = $('#produtoSubvencoesEstaduaisIds');
                if ($multi.length) $multi.val([]);
                $('#listaSubvencoesEstaduais').empty();
            }
        });

        function ajustarSubvEstadual() {
            if ($("#subvFederalContainer").is(":hidden")) {
                $("#subvEstadualContainer").addClass("ms-auto");
            } else {
                $("#subvEstadualContainer").removeClass("ms-auto");
            }
        }
        ajustarSubvEstadual();

        // --- Subvenções estaduais: várias por estado (Adicionar / Remover) ---
        // Multiselect pode ter id gerado pelo asp-for (ex: Produto_SubvencoesEstaduaisIds); usar name também
        var $multiSubv = $('#produtoSubvencoesEstaduaisIds').length ? $('#produtoSubvencoesEstaduaisIds') : $('select[name="Produto.SubvencoesEstaduaisIds"]');
        var $pickerSubv = $('#subvencaoEstadualPicker');
        var $listaSubv = $('#listaSubvencoesEstaduais');
        console.log('[Subvencoes] init: botão=', $('#btnAdicionarSubvencaoEstadual').length, 'multiselect=', $multiSubv.length, 'picker=', $pickerSubv.length, 'lista=', $listaSubv.length);

        function renderListaSubvencoesEstaduais() {
            var $multi = $('#produtoSubvencoesEstaduaisIds').length ? $('#produtoSubvencoesEstaduaisIds') : $('select[name="Produto.SubvencoesEstaduaisIds"]');
            var $lista = $('#listaSubvencoesEstaduais');
            if (!$lista.length) return;
            var emptyMsg = $lista.data('empty-msg') || 'Nenhuma subvenção adicionada.';
            $lista.empty();
            if (!$multi.length) return;
            var count = 0;
            $multi.find('option:selected').each(function () {
                var val = $(this).val();
                if (!val) return;
                count++;
                var text = $(this).text();
                $lista.append(
                    '<div class="d-flex align-items-center justify-content-between py-1 px-2 mb-1 border rounded bg-light" data-value="' + val + '">' +
                    '<span class="small">' + text + '</span>' +
                    '<button type="button" class="btn btn-sm btn-outline-danger py-0 removerSubvencaoEstadual" title="Remover">×</button>' +
                    '</div>'
                );
            });
            if (count === 0)
                $lista.html('<p class="text-muted small mb-0">' + emptyMsg + '</p>');
        }

        renderListaSubvencoesEstaduais();

        // Botão Adicionar: delegação para garantir que funcione (form pode carregar depois)
        console.log('[Subvencoes] Registrando handler do botão Adicionar (delegação em document)');
        $(document).off('click', '#btnAdicionarSubvencaoEstadual').on('click', '#btnAdicionarSubvencaoEstadual', function (e) {
            e.preventDefault();
            console.log('[Subvencoes] >>> CLIQUE ADICIONAR (botão subvenção estadual) <<<');
            console.log('[Subvencoes] Clique no botão Adicionar detectado');
            try {
                var $multi = $('#produtoSubvencoesEstaduaisIds').length ? $('#produtoSubvencoesEstaduaisIds') : $('select[name="Produto.SubvencoesEstaduaisIds"]');
                var $picker = $('#subvencaoEstadualPicker');
                var $lista = $('#listaSubvencoesEstaduais');
                console.log('[Subvencoes] multi=', $multi.length, 'picker=', $picker.length, 'lista=', $lista.length, '$multi[0]=', $multi[0] ? $multi[0].id || $multi[0].name : 'n/a');
                if (!$multi.length || !$picker.length || !$lista.length) {
                    console.warn('[Subvencoes] Saiu cedo: falta elemento. multi=' + $multi.length + ' picker=' + $picker.length + ' lista=' + $lista.length);
                    return;
                }
                var val = $picker.val();
                console.log('[Subvencoes] valor selecionado no picker:', val);
                if (!val) {
                    console.warn('[Subvencoes] Nenhuma subvenção escolhida no select (val vazio). Escolha uma opção antes de clicar Adicionar.');
                    return;
                }
                if ($multi.find('option[value="' + val + '"]').prop('selected')) {
                    console.warn('[Subvencoes] Subvenção já foi adicionada:', val);
                    return;
                }
                $multi.find('option[value="' + val + '"]').prop('selected', true);
                var text = $picker.find('option:selected').text();
                $lista.find('p.text-muted').remove();
                $lista.append(
                    '<div class="d-flex align-items-center justify-content-between py-1 px-2 mb-1 border rounded bg-light" data-value="' + val + '">' +
                    '<span class="small">' + text + '</span>' +
                    '<button type="button" class="btn btn-sm btn-outline-danger py-0 removerSubvencaoEstadual" title="Remover">×</button>' +
                    '</div>'
                );
                $picker.val('');
                console.log('[Subvencoes] Subvenção adicionada à lista:', text);
            } catch (err) {
                console.error('[Subvencoes] Erro ao adicionar:', err);
            }
        });
        console.log('[Subvencoes] Verificando se botão existe no DOM:', $('#btnAdicionarSubvencaoEstadual').length);

        $(document).off('click', '#listaSubvencoesEstaduais .removerSubvencaoEstadual').on('click', '#listaSubvencoesEstaduais .removerSubvencaoEstadual', function () {
            var row = $(this).closest('[data-value]');
            var val = row.data('value');
            var $multi = $('#produtoSubvencoesEstaduaisIds').length ? $('#produtoSubvencoesEstaduaisIds') : $('select[name="Produto.SubvencoesEstaduaisIds"]');
            if ($multi.length) $multi.find('option[value="' + val + '"]').prop('selected', false);
            row.remove();
            if ($('#listaSubvencoesEstaduais').children().length === 0) renderListaSubvencoesEstaduais();
        });




        // Toggle para Plantio Consorciado
        $('[name="Produto.AceitaPlantioConsorciado"]').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#plantioConsorciadoFields').show();
            } else {
                $('#plantioConsorciadoFields').hide();
            }
        });
        // Toggle para Plantio Convencional
        $('[name="Produto.AceitaPlantioConvencional"]').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#plantioConvencionalFields').show();
            } else {
                $('#plantioConvencionalFields').hide();
            }
        });
        // Toggle para Lavoura Irrigada
        $('[name="Produto.LavouraIrrigada"]').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#lavouraIrrigadaFields').show();
            } else {
                $('#lavouraIrrigadaFields').hide();
            }
        });
        // Toggle para Plantio Pós Cana
        $('[name="Produto.AceitaPlantioPosCanaDeAcucar"]').off('change').on('change', function () {
            if ($(this).is(':checked')) {
                $('#plantioPosCanaFields').show();
            } else {
                $('#plantioPosCanaFields').hide();
            }
        });


        // Atualize a chamada do evento change para usar a função do objeto
        $(document).off("change", ".taxa-uf").on("change", ".taxa-uf", function () {
            produtosJS.atualizarMunicipios($(this));
        });




        //Canais
        var channelIndex = $("#canalContainer .channel-block").length;

        $("#addCanalBtn").off("click").on("click", function () {
            var template = $("#canalTemplate").html();
            var newBlock = template.replace(/__INDEX__/g, channelIndex);
            $("#canalContainer").append(newBlock);
            channelIndex++;
        });

        $("#canalContainer").off("click", ".removeChannelBtn").on("click", ".removeChannelBtn", function () {
            $(this).closest(".channel-block").remove();
        });

        // Quando um canal é selecionado, carrega os pontos de atendimento via AJAX

        $("#CanalId").off("change").on("change", function () {
            var canalId = $(this).val();

            if (!canalId) {
                selected2.fillSelect("#PontoAtendimentoSelected", [], "Selecione");

                return;
            }
            $("#CanalId").val(canalId).trigger('change.select2');
            gl.Get("ListarPontosAtendimentoPorCanal", "PontoAtendimento", { canalId: canalId }, false, function (data) {
                if (data && data.length > 0) {
                    selected2.fillSelect("#PontoAtendimentoSelected", data, null);
                } else {
                    selected2.fillSelect("#PontoAtendimentoSelected", [], null);
                }

            });

        });



        // Evento delegado para remover uma linha de taxa
        $("#taxasContainer").off("click", ".removeTaxaBtn").on("click", ".removeTaxaBtn", function () {
            $(this).closest(".taxa-row").remove();
        });

        // Inicializa o índice com o número de linhas já existentes
        var taxaIndex = $("#taxasContainer .taxa-row").length;

        // Função para renderizar o template de taxa com o índice correto
        function renderizarTemplateTaxa(index) {
            var template = $("#taxaRowTemplate").html() || "";
            if (!template) {
                console.error("Template de taxa não encontrado");
                return "";
            }
            return template.replace(/__INDEX__/g, index);
        }

        $("#addTaxaBtn").off("click").on("click", function () {
            // Usa o template HTML para criar uma nova linha
            var newRow = renderizarTemplateTaxa(taxaIndex);
            $("#taxasContainer").append(newRow);

            Basics.currencyMask(".currency");
            Basics.taxaMask(".taxamask");
            taxaIndex++;
        });

        // Botão para importar CSV

        produtosJS.initCanalPontoAtendimento();
        produtosJS.initTaxas();

        // Add event listeners for the buttons
        $("#btDuplicar").off('click').on('click', function() {
            var id = $(this).data('id');
            produtosJS.duplicarProduto(id);
        });

        $("#btToggleAtivo").off('click').on('click',  function() {
            var id = $(this).data('id');
            var isAtivo = $(this).data('ativo');
            produtosJS.toggleAtivoProduto(id, isAtivo);
        });

        $("#btDelete").off('click').on('click', function() {
            var id = $(this).data('id');
            produtosJS.excluirProduto(id);
        });

        // Inicializa todos os dropdowns
        var dropdownElementList = [].slice.call(document.querySelectorAll('.dropdown-toggle'))
        var dropdownList = dropdownElementList.map(function (dropdownToggleEl) {
            return new bootstrap.Dropdown(dropdownToggleEl)
        });
    },
    onSuccessCallback: function (r) {
        if (r.success == true) {
            notify.success("Produto Salvo", r.message, function () {
                window.location.href = "/ProdutosPage";
            });
        } else
            notify.error(r.message);
    },
    canalOnSuccessCallback: function (r) {
        if (r.success == true) {
            produtosJS.refreshCanalPontoAtendimentoList();

            notify.success("Canais e Pontos de Atendimento", r.message, function (d) {
                //window.location.href = "/Produtos/Index";
            });

            $("#PontoAtendimentoSelected").val(null).trigger('change');

        } else
            notify.error(r.message);
    },

    refreshCanalPontoAtendimentoList: function () {
        gl.RenderGet("ProdutosCanalList", "ProdutosCanal", { produtoId: $("#Produto_Id").val() }, "#canalPAList", true, null, function () {
            produtosJS.initCanalPontoAtendimento();
        });
    },
    initCanalPontoAtendimento: function () {
        $(".paRemove").off("click").on("click", function (e) {
            e.preventDefault();
            var pontoAtendimentoId = $(this).data("id");
            notify.confirmYesNo(
                "danger",
                "Excluir Ponto de Atendimento?",
                "Tem certeza que deseja excluir este ponto de atendimento?",
                function (confirmed) {

                    gl.Post("Excluir", "ProdutosCanal", { pontoAtendimentoId: pontoAtendimentoId, __RequestVerificationToken: gl.GetToken() }, true, function (r) {
                        produtosJS.refreshCanalPontoAtendimentoList();
                    });
                },
                null,
                "Sim, excluir",
                "Cancelar"
            );
        });

        // Toggle para marcar/desmarcar todos os pontos de atendimento
        $("#toggleSelectAllPA").off("click").on("click", function () {
            var $select = $("#PontoAtendimentoSelected");
            var allSelected = $select.find("option:selected").length === $select.find("option").length;
            if (!allSelected) {
                $select.find("option").prop("selected", true);
                $(this).text("Desmarcar Todos");
            } else {
                // Desmarca todos
                $select.find("option").prop("selected", false);
                $(this).text("Marcar Todos os P.As");
            }
            $select.trigger("change"); // Atualiza o Select2
        });

        // Atualiza o texto do botão conforme a seleção
        $("#PontoAtendimentoSelected").on("change", function () {
            var $select = $(this);
            var $btn = $("#toggleSelectAllPA");
            var allSelected = $select.find("option:selected").length === $select.find("option").length - 1;
            $btn.text(allSelected ? "Desmarcar Todos" : "Marcar Todos os P.As");
        });
    },
    taxaOnSuccessCallback: function (r) {
        if (r.success == true) {
            location.reload();
        } else
            notify.error(r.message);
    },

    refreshTaxasList: function () {
        // Esconde a tabela atual
        $('#tabelaTaxas').hide();
        $('#tabelaTaxasLoading').show();

        gl.RenderGet("ProdutosTaxasList", "ProdutosTaxas", { produtoId: $("#Produto_Id").val() }, "#taxaList", true, null, function () {
            // Aumenta o tempo de espera para garantir que o DOM foi atualizado
            setTimeout(function () {
                produtosJS.initTaxas();
            }, 300); // Aumentado para 300ms
        });
    },
    initTaxas: function () {
        $('.selected2').select2();
        Basics.maskCpf('.taxa-cpf');

        // Mostra o indicador de carregamento
        $('#tabelaTaxasLoading').show();

        // Inicialização do DataTables
        var table = $('#tabelaTaxas');

        try {
            // Verifica se a tabela existe no DOM
            if (!table.length) {
                $('#tabelaTaxasLoading').hide();
                return;
            }

            // Destrói a tabela existente se ela já foi inicializada
            if ($.fn.DataTable.isDataTable('#tabelaTaxas')) {
                table.DataTable().destroy();
                table.empty(); // Limpa o conteúdo da tabela
            }

            // Inicializa a nova tabela
            table.DataTable({
                "language": {
                    "url": "//cdn.datatables.net/plug-ins/1.13.8/i18n/pt-BR.json"
                },
                "pagingType": "full_numbers",
                "pageLength": 25,
                "lengthMenu": [[10, 25, 50, 100, -1], [10, 25, 50, 100, "Todos"]],
                "responsive": true,
                "order": [[0, 'asc'], [1, 'asc']], // Ordena por UF e depois por Município
                "columnDefs": [
                    {
                        "targets": -1, // Última coluna (Ações)
                        "orderable": false,
                        "searchable": false
                    }
                ],
                "initComplete": function () {
                    // Mostra a tabela e esconde o indicador de carregamento
                    table.css('visibility', 'visible');
                    $('#tabelaTaxasLoading').hide();
                    
                    // Adiciona estilo para paginação horizontal
                    $('.dataTables_paginate').css({
                        'display': 'flex',
                        'flex-direction': 'row',
                        'align-items': 'center',
                        'justify-content': 'center',
                        'gap': '5px'
                    });
                    $('.paginate_button').css({
                        'display': 'inline-block',
                        'margin': '0 2px'
                    });
                }
            });
        } catch (error) {
            $('#tabelaTaxasLoading').hide();
        }

        // Bind para o botão de remoção de taxa
        $(document).off("click", ".taxaRemove").on("click", ".taxaRemove", function () {
            var taxaId = $(this).data("id");
            var produtoId = $("#Produto_Id").val();
            
            notify.confirmYesNo(
                "danger",
                "Confirmação de Exclusão",
                "Tem certeza que deseja excluir esta taxa?",
                function (confirmed) {
                    if (confirmed) {
                        gl.Post("Excluir", "ProdutosTaxas", { 
                            taxaId: taxaId,
                            produtoId: produtoId,
                            __RequestVerificationToken: gl.GetToken() 
                        }, true, function (r) {
                            if (r.success) {
                                notify.success("Sucesso", "Taxa removida com sucesso");
                                produtosJS.refreshTaxasList();
                            } else {
                                notify.error("Erro", r.message || "Ocorreu um erro ao remover a taxa.");
                            }
                        });
                    }
                },
                null,
                "Sim, excluir",
                "Cancelar"
            );
        });

        // Add handler for the "Remove All Rates" button
        $("#removerTodasTaxasBtn").off("click").on("click", function (e) {
            if ($(this).text().trim() === "Remover Todas as Taxas") {
                e.preventDefault();
                var produtoId = $("#Produto_Id").val();
                notify.confirmYesNo(
                    "danger",
                    "Excluir Todas as Taxas?",
                    "Tem certeza que deseja excluir todas as taxas? Esta ação não pode ser desfeita.",
                    function (confirmed) {
                        gl.Post("ExcluirTodas", "ProdutosTaxas", { produtoId: produtoId, __RequestVerificationToken: gl.GetToken() }, true, function (r) {
                            if (r.success) {
                                notify.success("Sucesso", r.message);
                                produtosJS.refreshTaxasList();
                            } else {
                                notify.error("Erro", r.message);
                            }
                        });
                    },
                    null,
                    "Sim, excluir",
                    "Cancelar"
                );
            }
        });

        // Evento delegado para editar uma taxa
        $("#taxasContainer").off("click", ".taxaEdit").on("click", ".taxaEdit", function (e) {
            e.preventDefault();
            var taxaId = $(this).data("id");
            gl.Get("ObterById", "ProdutosTaxas", { taxaId: taxaId, __RequestVerificationToken: gl.GetToken() }, true, async function (r) {
                // Preencher os campos do formulário com os dados da taxa
                $("#formProdutosCanal select[name=UF]").val(r.uf).trigger('change');
                
                // Aguarda o carregamento dos municípios usando a função do objeto
                await produtosJS.atualizarMunicipios($("#formProdutosCanal select[name=UF]"), r.municipio);

                // Formatar valores numéricos para o formato brasileiro
                $("#formProdutosCanal input[name=ProdutividadeEsperada]").val(r.produtividadeEsperada.toString().replace('.', ','));
                $("#formProdutosCanal input[name=TaxaNc65]").val(r.taxaNc65.toString().replace('.', ','));
                $("#formProdutosCanal input[name=TaxaNc70]").val(r.taxaNc70.toString().replace('.', ','));
                $("#formProdutosCanal input[name=TaxaNc75]").val(r.taxaNc75.toString().replace('.', ','));

                // Preencher CPF e ID da taxa
                $("#formProdutosCanal input[name=Cpf]").val(r.cpf);
                $("#formProdutosCanal input[name=ProdutoTaxaId]").val(r.produtoTaxaId);
                $("#btTaxaAdd").text("Atualizar Taxa");
            });
        });

        // Configuração do botão de importação de taxas via CSV
        $("#importarTaxasBtn").off("click").on("click", function (e) {
            e.preventDefault();

            // Criar um modal para o Dropzone
            var modalId = "dropzoneModal";
            var modalHtml = `
                <div class="modal fade" id="${modalId}" tabindex="-1" role="dialog" aria-labelledby="${modalId}Label" aria-hidden="true">
                    <div class="modal-dialog modal-lg" role="document">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title" id="${modalId}Label">Importar Taxas CSV</h5>
                                <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                                    <span aria-hidden="true">&times;</span>
                                </button>
                            </div>
                            <div class="modal-body">
                                <p>
                                    <strong>Modelo de importação:</strong><br>
                                </p>
                                <a href="/files/modelo.csv" download class="btn btn-outline-primary mb-3">
                                    📥 Baixar modelo CSV
                                </a>
                                <div id="taxasDropzone" class="dropzone mt-3"></div>
                            </div>
                            <div class="modal-footer">
                                <button type="button" class="btn btn-secondary" data-dismiss="modal">Fechar</button>
                            </div>
                        </div>
                    </div>
                </div>
            `;

            // Remover modal existente se houver
            $("#" + modalId).remove();

            // Adicionar o modal ao body
            $("body").append(modalHtml);

            // Inicializar o Dropzone
            var myDropzone = new Dropzone("#taxasDropzone", {
                url: "/ProdutosTaxas/ImportarTaxas",
                paramName: "file",
                maxFilesize: 10, // MB
                acceptedFiles: ".csv",
                addRemoveLinks: true,
                dictDefaultMessage: "Arraste o arquivo CSV aqui ou clique para selecionar",
                dictRemoveFile: "Remover arquivo",
                autoProcessQueue: true,
                maxFiles: 1,
                init: function () {
                    this.on("sending", function (file, xhr, formData) {
                        gl.BeginAjax();
                        formData.append("produtoId", $("#Produto_Id").val());
                        formData.append("__RequestVerificationToken", gl.GetToken());
                    });

                    this.on("success", function (file, response) {
                        if (response.success) {
                            notify.success("Sucesso", response.message);
                            $("#" + modalId).modal("hide");
                            produtosJS.refreshTaxasList();
                        } else {
                            notify.error("Erro", response.message || "Erro ao importar taxas.");
                            $("#" + modalId).modal("hide");
                        }
                        this.removeAllFiles();
                        gl.CompleteAjax();
                    });

                    this.on("error", function (file, errorMessage) {
                        notify.error("Erro", typeof errorMessage === "string" ? errorMessage : "Falha ao processar o arquivo CSV.");
                        this.removeAllFiles();
                        $("#" + modalId).modal("hide");
                        gl.CompleteAjax();
                    });

                    this.on("complete", function () {
                        gl.CompleteAjax();
                    });
                }
            });

            $("[data-dismiss='modal']").off("click").on("click", function () {
                $("#" + modalId).modal("hide");
            });
            // Mostrar o modal
            $("#" + modalId).modal("show");
        });
    },
    atualizarMunicipios: async function($ufSelect, municipioSelecionado = null) {
        // Função auxiliar para normalizar o nome da cidade
        function normalizarNomeCidade(nome) {
            if (!nome) return '';
            return nome.toLowerCase()
                .split(' ')
                .map(palavra => palavra.charAt(0).toUpperCase() + palavra.slice(1))
                .join(' ');
        }

        // Obtém o valor do estado a partir do select de UF
        var estado = $ufSelect.val();
        // Encontra o select de município na mesma linha (taxa-row)
        var $municipioSelect = $ufSelect.closest('.taxa-row').find('.taxa-municipio');

        if (!estado) {
            $municipioSelect.empty().append('<option value="">Selecione primeiro um estado</option>');
            return;
        }

        try {
            $municipioSelect.empty().append('<option value="">Carregando...</option>');
            const municipios = await carregarMunicipios(estado);

            $municipioSelect.empty().append('<option value="">Selecione o município</option>');
            
            // Normaliza o nome do município selecionado
            const municipioSelecionadoNormalizado = normalizarNomeCidade(municipioSelecionado);

            municipios.forEach(municipio => {
                // Normaliza o nome do município da API
                const nomeMunicipioNormalizado = normalizarNomeCidade(municipio.nome);
                
                $municipioSelect.append(
                    $('<option>', {
                        value: municipio.nome, // Mantém o valor original da API
                        text: municipio.nome,  // Mantém o texto original da API
                        selected: municipioSelecionado && 
                                 nomeMunicipioNormalizado === municipioSelecionadoNormalizado
                    })
                );
            });
            
            return new Promise(resolve => {
                $municipioSelect.trigger('change');
                resolve();
            });
        } catch (error) {
            $municipioSelect.empty().append('<option value="">Erro ao carregar municípios</option>');
            alert("Não foi possível carregar a lista de municípios. Por favor, tente novamente.");
        }
    },

    duplicarProduto: function(id) {
        notify.confirmYesNo(
            "primary",
            "Confirmação de Duplicação",
            "Tem certeza que deseja duplicar este produto?",
            function (confirmed) {
                if (confirmed) {
                    gl.Post("Duplicar", "ProdutosPage", { id: id }, true, function (r) {
                        if (r.success) {
                            notify.success("Sucesso", "Produto Duplicado.");
                            setTimeout(function() {
                                window.location.href = "/ProdutosPage/Gerenciar/" + r.produtoId;
                            }, 1000);
                        } else {
                            notify.error("Erro", r.message);
                        }
                    });
                }
            },
            null,
            "Sim, duplicar",
            "Cancelar"
        );
    },

    excluirProduto: function (id) {
        notify.confirmYesNo(
            "danger",
            "Confirmação de Exclusão",
            "Tem certeza que deseja excluir este produto?",
            function (confirmed) {
                if (confirmed) {
                    gl.Post("Excluir", "ProdutosPage", { id: id }, true, function (r) {
                        if (r.success) {
                            notify.success("Sucesso", r.message);
                            setTimeout(function() {
                                window.location.reload();
                            }, 1000);
                        } else {
                            notify.error("Erro", r.message);
                        }
                    });
                }
            },
            null,
            "Sim, excluir",
            "Cancelar"
        );
    },

    toggleAtivoProduto: function (id, isAtivo) {
        isAtivo = isAtivo === 'True';
        
        notify.confirmYesNo(
            "warning",
            "Confirmação de Alteração de Status",
            "Tem certeza que deseja alterar o status deste produto?",
            function (confirmed) {
                if (confirmed) {
                    gl.Post("ToggleAtivo", "ProdutosPage", { id: id }, true, function (r) {
                        if (r.success) {
                            notify.success("Sucesso", r.message);
                            setTimeout(function() {
window.location.href = "/ProdutosPage?pesquisaAtivoInativo=Todos";
                            }, 1000);
                        } else {
                            notify.error("Erro", r.message);
                        }
                    });
                }
            },
            null,
            "Sim, alterar status",
            "Cancelar"
        );
    }
};

$(document).ready(function () {
    produtosJS.init();
});
